

function formatDateDDMMYYYY(v){
  if(!v) return '';
  const s=String(v);
  const m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if(m) return `${m[3]}-${m[2]}-${m[1]}`;
  const d=new Date(v);
  if(!isNaN(d.getTime())){
    return String(d.getDate()).padStart(2,'0')+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+d.getFullYear();
  }
  return s;
}

/* =========================================================================
   KHURJA DSM CALCULATOR
   Data model: state.weeks[1..52] = { days:[ {date, blocks:[...]} ], originalDays }
   Block = { t (time label), s (sch MWh), a (act MWh), f (freq Hz), r (rate ₹/kWh) }
   Calculation engine validated against KHURJA_W1.xlsx precomputed charges
   (matches to rounding on every sampled block).
   ========================================================================= */

const BLOCKS_PER_DAY = 96;
const WEEK_COUNT = 52;
const STORAGE_PREFIX = 'khurja-week:';

const state = {
  weeks: {},          // weekNum -> { days:[...], originalDays:[...] }
  currentWeek: 1,
  currentDate: null,  // selected date string for drill-down
  charts: {},         // chart.js instances
  storageAvailable: !!(window.storage),
  view: 'home',        // 'home' | 'week'
  auth: { loggedIn:false, mobile:null },
  pendingOtp: null,    // in-memory only, never persisted
  projectMeta: { name:'Khurja DSM Calculator', plant:'11 MW Khurja Floating Solar Power Plant' }
};

for(let w=1; w<=WEEK_COUNT; w++){ state.weeks[w] = { days: [], originalDays: [] }; }

/* ---------------- calculation engine (validated, now parameterized) ---------------- */
const DEFAULT_FORMULA_PARAMS = {
  volLimitPct: 10,        // % of schedule used for volume limit + the ±X% split threshold
  volLimitCap: 25,        // MWh cap on volume limit
  deadbandLow: 49.97,     // Hz — below this, ramp begins
  deadbandHigh: 50.03,    // Hz — above this, ramp begins
  bandLow: 49.90,         // Hz — outer boundary (below = deep under-frequency)
  bandHigh: 50.05,        // Hz — outer boundary (above = discount / over-freq zone)
  extremeHigh: 50.10,     // Hz — beyond this, over-injection multiplier reverses (goes negative)
  // Over-injection (Actual > Schedule) multiplier ramp, within volume limit
  overBelowBandMult: 1.15,   // multiplier when f < bandLow
  overRampLowSlope: 0.0215,  // multiplier increase per 0.01 Hz as f falls from deadbandLow to bandLow
  overRampLowCap: 1.15,      // max multiplier reached in that ramp
  overRampHighSlope: 0.25,   // multiplier decrease per 0.01 Hz as f rises from deadbandHigh to bandHigh
  overRampHighFloor: 0.5,    // min multiplier reached in that ramp
  overDiscountMult: 0,       // multiplier when bandHigh < f < extremeHigh
  overExtremeMult: -0.1,     // multiplier when f >= extremeHigh
  // Under-injection (Actual < Schedule) multiplier ramp, within volume limit
  underBelowBandMult: 1.5,
  underRampLowSlope: 0.0715,
  underRampLowCap: 1.5,
  underRampHighSlope: 0.075,
  underRampHighFloor: 0.85,
  underAboveBandMult: 0.85,  // multiplier when f > bandHigh
  // Beyond-limit multipliers (deviation beyond the volume limit)
  beyondUnderHighMult: 1,    // under-injection, f >= 50
  beyondUnderMidMult: 1.5,   // under-injection, bandLow <= f < 50
  beyondUnderLowMult: 2,     // under-injection, f < bandLow
};
let FP = {...DEFAULT_FORMULA_PARAMS}; // active formula params (mutable, persisted via window.storage)

function multWithinOver(h){
  if(h>=FP.deadbandLow && h<=FP.deadbandHigh) return 1;
  if(h>FP.deadbandHigh && h<=FP.bandHigh) return Math.max(FP.overRampHighFloor, 1-((h-FP.deadbandHigh)/0.01)*FP.overRampHighSlope);
  if(h>=FP.bandLow && h<FP.deadbandLow) return Math.min(FP.overRampLowCap, 1+((FP.deadbandLow-h)/0.01)*FP.overRampLowSlope);
  if(h>FP.bandHigh && h<FP.extremeHigh) return FP.overDiscountMult;
  if(h>=FP.extremeHigh) return FP.overExtremeMult;
  if(h<FP.bandLow) return FP.overBelowBandMult;
  return 1;
}
function multWithinUnder(h){
  if(h>=FP.deadbandLow && h<=FP.deadbandHigh) return 1;
  if(h>FP.deadbandHigh && h<=FP.bandHigh) return Math.max(FP.underRampHighFloor, 1-((h-FP.deadbandHigh)/0.01)*FP.underRampHighSlope);
  if(h>=FP.bandLow && h<FP.deadbandLow) return Math.min(FP.underRampLowCap, 1+((FP.deadbandLow-h)/0.01)*FP.underRampLowSlope);
  if(h>FP.bandHigh) return FP.underAboveBandMult;
  if(h<FP.bandLow) return FP.underBelowBandMult;
  return 1;
}
function multBeyondMain(devType,h){
  if(devType==='Over-Injection') return h<FP.extremeHigh ? FP.overDiscountMult : FP.overExtremeMult;
  if(h>=50) return FP.beyondUnderHighMult;
  if(h>=FP.bandLow) return FP.beyondUnderMidMult;
  return FP.beyondUnderLowMult;
}
function computeBlock(s,a,f,r){
  s = Number(s)||0; a = Number(a)||0; f = Number(f)||0; r = Number(r)||0;
  const pct = FP.volLimitPct/100;
  const dev = a - s;
  const devPct = s===0 ? 0 : (dev/Math.abs(s))*100;
  const devType = dev>0 ? 'Over-Injection' : (dev<0 ? 'Under-Injection' : 'No Deviation');
  const volLimit = Math.min(s*pct, FP.volLimitCap);
  const freqBand = (f>=FP.bandLow && f<=FP.bandHigh) ? 'Within f-band' : 'Outside f-band';

  let multWithin;
  if(s===0){ multWithin = dev>0 ? 0 : 1; }
  else if(dev>0){ multWithin = multWithinOver(f); }
  else { multWithin = multWithinUnder(f); }

  let devWithin;
  if(Math.abs(dev) > s*pct) devWithin = -volLimit;
  else if(Math.abs(devPct) > FP.volLimitPct) devWithin = dev*FP.volLimitPct/Math.abs(devPct);
  else devWithin = dev;

  let devBeyond;
  if(s===0) devBeyond = dev - devWithin;
  else if(Math.abs(devPct) > FP.volLimitPct) devBeyond = dev - devWithin;
  else devBeyond = 0;

  let multBeyond;
  if(s===0){
    if(devType==='Under-Injection' && f>=FP.bandLow && f<=FP.bandHigh) multBeyond=1;
    else if(f>=FP.bandLow && f<=FP.bandHigh) multBeyond=0;
    else if(devType==='Under-Injection' && f>FP.bandLow) multBeyond=1;
    else if(devType==='Over-Injection' && f>=FP.bandLow && f<FP.bandHigh) multBeyond=0;
    else if(f<FP.bandLow) multBeyond=1;
    else multBeyond = multBeyondMain(devType,f);
  } else {
    multBeyond = multBeyondMain(devType,f);
  }

  const magnitude = Math.abs(devWithin)*multWithin + Math.abs(devBeyond)*multBeyond;
  let charge;
  if(dev===0) charge = 0;
  else if(dev>0) charge = -1*magnitude*r*1000;
  else charge = magnitude*r*1000;
  charge = Math.round(charge);

  return {dev, devPct, devType, volLimit, freqBand, multWithin, devWithin, devBeyond, multBeyond, charge};
}

/* ---------------- helpers ---------------- */
function fmtMWh(x){ return (Math.round(x*1000)/1000).toLocaleString('en-IN',{minimumFractionDigits:3,maximumFractionDigits:3}); }
function fmtMWh0(x){ return (Math.round(x*100)/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function fmtInr(x){
  const r = Math.round(x);
  const sign = r<0 ? '-' : '';
  return '₹'+sign+Math.abs(r).toLocaleString('en-IN');
}
function fmtRate(x){ return (Math.round(x*1000)/1000).toFixed(3); }
function fmtPct(x){ return (Math.round(x*10)/10).toFixed(1)+'%'; }
function weekObj(){ return state.weeks[state.currentWeek]; }

function dayAgg(day){
  let s=0,a=0,charge=0,over=0,under=0,none=0;
  for(const b of (day?.blocks||[])){
    const r=revisionAwareBlock(day,b);
    s+=Number(r.s)||0; a+=Number(b.a)||0; charge+=Number(r.charge)||0;
    if(r.dev>0)over++; else if(r.dev<0)under++; else none++;
  }
  return {blocks:(day?.blocks||[]).length,s,a,dev:a-s,charge,over,under,none,avgRate:(day?.blocks||[]).reduce((x,b)=>x+(Number(b.r)||0),0)/((day?.blocks||[]).length||1)};
}
function weekAgg(week){
  let s=0,a=0,dev=0,charge=0,over=0,under=0,none=0,maxPos=0,maxNeg=0,rateSum=0,rateN=0;
  week.days.forEach(d=>{
    const g = dayAgg(d);
    s+=g.s; a+=g.a; dev+=g.dev; charge+=g.charge; over+=g.over; under+=g.under; none+=g.none;
    if(g.maxPos>maxPos) maxPos=g.maxPos;
    if(g.maxNeg<maxNeg) maxNeg=g.maxNeg;
    d.blocks.forEach(b=>{ rateSum+=Number(b.r||0); rateN++; });
  });
  const totalBlocks = over+under+none;
  return {s,a,dev,charge,over,under,none,maxPos,maxNeg,totalBlocks,avgRate: rateN? rateSum/rateN : 0,
          avgDev: totalBlocks ? dev/totalBlocks : 0};
}
function dataQuality(week){
  let valid=0, total=0, issues=[];
  week.days.forEach(d=>{
    if(d.blocks.length !== BLOCKS_PER_DAY) issues.push(d.date+': '+d.blocks.length+'/96 blocks');
    d.blocks.forEach(b=>{
      total++;
      const ok = b.s!==null && b.a!==null && !isNaN(b.s) && !isNaN(b.a) && b.f!==null && !isNaN(b.f) && b.r!==null && !isNaN(b.r);
      if(ok) valid++;
    });
  });
  const expectedTotal = week.days.length * BLOCKS_PER_DAY;
  return {valid, total, expectedTotal, missingDays: 7-week.days.length, issues};
}

/* ---------------- storage ---------------- */
async function saveWeek(n){
 try{
  const id=String(window.currentPlantContext||'Khurja Floating Solar').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  localStorage.setItem('thdc-dsm-v2:'+id+':week:'+n,JSON.stringify(state.weeks[n]));
  if(window.storage) await window.storage.set(STORAGE_PREFIX+n,JSON.stringify(state.weeks[n]),false);
 }catch(e){console.error('storage save failed',e)}
}
async function loadAllWeeks(){
  // Cloud storage is optional; standalone Chrome uses the plant-wise localStorage layer.
  if(!window.storage) return;
  try{
    const list = await window.storage.list(STORAGE_PREFIX, false);
    if(!list || !list.keys) return;
    for(const k of list.keys){
      try{
        const res = await window.storage.get(k, false);
        if(res && res.value){
          const n = parseInt(k.replace(STORAGE_PREFIX,''),10);
          if(n>=1 && n<=WEEK_COUNT) state.weeks[n] = JSON.parse(res.value);
        }
      }catch(e){}
    }
  }catch(e){ console.error('storage list failed', e); }
}
async function saveAuth(){
  if(!window.storage) return;
  try{ await window.storage.set('khurja-auth', JSON.stringify(state.auth), false); }catch(e){}
}
async function loadAuth(){
  if(!window.storage) return;
  try{
    const res = await window.storage.get('khurja-auth', false);
    if(res && res.value) state.auth = JSON.parse(res.value);
  }catch(e){}
}
async function clearAuth(){
  state.auth = { loggedIn:false, mobile:null };
  if(!window.storage) return;
  try{ await window.storage.delete('khurja-auth', false); }catch(e){}
}
async function saveProjectMeta(){
  if(!window.storage) return;
  try{ await window.storage.set('khurja-project-meta', JSON.stringify(state.projectMeta), false); }catch(e){}
}
async function loadProjectMeta(){
  if(!window.storage) return;
  try{
    const res = await window.storage.get('khurja-project-meta', false);
    if(res && res.value) state.projectMeta = JSON.parse(res.value);
  }catch(e){}
}
async function saveFormulaParams(){
  if(!window.storage) return;
  try{ await window.storage.set('khurja-formula-params', JSON.stringify(FP), false); }catch(e){}
}
async function loadFormulaParamsFromStorage(){
  if(!window.storage) return;
  try{
    const res = await window.storage.get('khurja-formula-params', false);
    if(res && res.value){ FP = {...DEFAULT_FORMULA_PARAMS, ...JSON.parse(res.value)}; }
  }catch(e){}
}

