function seedWeek1(){
  const days = W1_SEED.map(d=>({
    date: d.date,
    blocks: d.blocks.map((b,i)=>({ idx:i+1, t:b[0], s:b[1]/1000, a:b[2]/1000, f:b[3], r:b[4] }))
  }));
  state.weeks[1].days = days;
  state.weeks[1].originalDays = JSON.parse(JSON.stringify(days));
}

/* ================= RENDER: SHELL ================= */
function renderShell(){
  const app = document.getElementById('app');
  app.innerHTML = `
    <div class="topbar">
      <div class="topbar-left">
        <div class="project-title-row"><h1>${state.projectMeta.plant || state.projectMeta.name}</h1></div>
        <div class="sub">${state.projectMeta.plant} · <b>CERC DSM Regulations 2024</b> · 7 Days · 672 Blocks / week</div>
      </div>
      <div class="topbar-right">
        <div class="nav-tabs"><div class="nav-tab" onclick="goHome()">🏠 Home</div><div class="nav-tab active">📊 Week View</div></div><div class="thdc-save-controls"><button class="btn btn-primary btn-sm" onclick="THDC_MANUAL_SAVE()">💾 Save Data</button><button class="btn btn-sm" onclick="THDC_EXPORT_BACKUP()">⇩ Backup</button><button class="btn btn-sm" onclick="THDC_IMPORT_BACKUP()">⇧ Restore</button><span class="thdc-save-status" data-save-status>Not saved yet</span></div>
        <div class="week-select-wrap">
          <label>Week</label>
          <select id="weekSelect" onchange="onWeekChange(this.value)"></select>
        </div>
        <button class="btn btn-primary" onclick="openModal('pasteModal')">⇪ Paste Excel Data</button>
        <button class="btn" onclick="openRevisionManager()">↻ Revisions</button>
        <button class="btn" onclick="exportWeek()">⇩ Export Excel</button>
        <button class="btn btn-primary" id="exportColorPdfBtn" onclick="exportPDF()">▣ Export Color PDF</button>
        <button class="btn" onclick="openFormulaModal()">⚙ Formula Settings</button>
        <button class="btn" onclick="confirmResetWeek()">Reset Week</button>
        <button class="btn btn-danger" onclick="confirmClearWeek()">Clear Week</button>
        <button class="btn btn-danger" onclick="confirmClearAll()">Clear All</button>
        <div class="user-chip">📱 <b>${state.auth.mobile||''}</b><button onclick="logout()">Logout</button></div>
      </div>
    </div>
    <div id="qualityBanner"></div>
    <div class="panel" id="heatstripPanel"></div>
    <div class="kpi-grid" id="kpiGrid"></div>
    <div class="kpi-grid-sec" id="kpiGridSec"></div>
    <div class="charts-row">
      <div class="panel"><div class="panel-head"><div class="panel-title">Scheduled vs Actual <span class="n">date-wise, MWh</span></div></div><div class="chart-box"><canvas id="chartSchAct"></canvas></div></div>
      <div class="panel"><div class="panel-head"><div class="panel-title">Daily Deviation <span class="n">MWh, by date</span></div></div><div class="chart-box"><canvas id="chartDev"></canvas></div></div>
    </div>
    <div class="charts-row">
      <div class="panel"><div class="panel-head"><div class="panel-title">Daily DSM Charge <span class="n">₹, by date</span></div></div><div class="chart-box"><canvas id="chartCharge"></canvas></div></div>
      <div class="panel">
        <div class="panel-head"><div class="panel-title">Over / Under-Injection <span class="n">week totals</span></div></div>
        <div style="display:grid;grid-template-columns:200px 1fr;gap:16px;align-items:center;">
          <div class="chart-box" style="height:190px;"><canvas id="chartInjDonut"></canvas></div>
          <div class="inj-grid" id="injGrid" style="grid-template-columns:1fr;gap:10px;"></div>
        </div>
      </div>
    </div>

<div class="panel" id="frequencyResponsePanel">
  <div class="panel-head">
    <div class="panel-title">⚡ Frequency Response Analysis <span class="n">frequency vs plant deviation — all 96 blocks/day</span></div>
  </div>
  <div style="display:grid;grid-template-columns:1.7fr 1fr;gap:14px;align-items:start;">
    <div style="position:relative;height:270px;"><canvas id="frequencyResponseTimelineChart"></canvas></div>
    <div id="frequencyResponseKPIs"></div>
  </div>
  <div id="frequencyResponseExplanation" style="margin-top:10px;"></div>
  <div class="panel" style="margin:10px 0 0;padding:10px;background:#FBFDFF;">
    <div class="panel-title" style="font-size:11px;">Grid Stress / Stabilization Timeline</div>
    <div id="frequencyResponseMiniTable" style="margin-top:7px;"></div>
  </div>
</div>

<div class="panel" id="optimizationInsightsPanel" style="display:none; border-top: 3px solid var(--amber);">
  <div class="panel-head">
    <div class="panel-title">💡 Optimization Insights <span class="n">AI-driven schedule adjustments to minimize DSM debits</span></div>
  </div>
  <div id="optimizationInsightsContent"></div>
</div>

    <div class="panel">
      <div class="panel-head"><div class="panel-title">Weekly Summary</div></div>
      <div id="weeklySummary"></div>
    </div>
    <div class="panel">
      <div class="panel-head"><div class="panel-title">Date-wise Analysis <span class="n">click a row to inspect all 96 blocks</span></div></div>
      <div id="dateTable"></div>
    </div>
    <div class="panel" id="dayDetailPanel" style="display:none;"></div>
    <footer>
      Calculation engine reproduces the source workbook's <code>Calculation</code> sheet exactly: volume limit = MIN(10% of schedule, 25 MWh);
      frequency-linked multipliers ramp between 49.90–49.97 Hz and 50.03–50.05 Hz around a 49.97–50.03 Hz deadband; deviation beyond ±10% of
      schedule is split into within-limit / beyond-limit portions and charged separately at ₹/kWh × 1000 scaling, matching <code>KHURJA_W1.xlsx</code>
      block-level charges to the rupee. ${state.storageAvailable ? 'Data persists automatically in this session.' : 'Persistent storage is unavailable in this context — data will reset if the page is closed; use Export Week to keep a copy.'}
    </footer>
  `;
  const sel = document.getElementById('weekSelect');
  sel.innerHTML = Array.from({length:WEEK_COUNT},(_,i)=>i+1).map(n=>{
    const has = state.weeks[n].days.length>0;
    return `<option value="${n}" ${n===state.currentWeek?'selected':''}>W${n}${has?' •':''}</option>`;
  }).join('');
}

function onWeekChange(v){
  state.currentWeek = parseInt(v,10);
  state.currentDate = null;
  renderAll();
  if(typeof updateTopWorkspaceContext==='function') setTimeout(updateTopWorkspaceContext,20);
  if(window.THDC_MANUAL_SAVE) THDC_MANUAL_SAVE();
}

/* ================= NAVIGATION: HOME <-> WEEK VIEW ================= */
function goHome(){ state.view='home'; renderHomeShell();
  if(typeof updateTopWorkspaceContext==='function') setTimeout(updateTopWorkspaceContext,20); }
function goWeekView(weekNum){
  if(weekNum) state.currentWeek = weekNum;
  state.view = 'week';
  state.currentDate = null;
  renderShell();
  if(typeof updateTopWorkspaceContext==='function') setTimeout(updateTopWorkspaceContext,20);
  renderAll();
}

/* ================= HOME DASHBOARD ================= */
function renderHomeShell(){
  const app = document.getElementById('app');
  let totalWeeksLoaded=0, totalBlocks=0, totalS=0, totalA=0, totalDev=0, totalCharge=0;
  for(let w=1; w<=WEEK_COUNT; w++){
    const wk = state.weeks[w];
    if(wk.days.length>0){
      totalWeeksLoaded++;
      const g = weekAgg(wk);
      totalBlocks += g.totalBlocks; totalS += g.s; totalA += g.a; totalDev += g.dev; totalCharge += g.charge;
    }
  }
  const weekCards = Array.from({length:WEEK_COUNT},(_,i)=>i+1).map(n=>{
    const wk = state.weeks[n];
    const has = wk.days.length>0;
    if(!has) return `<div class="home-week-card empty-week" onclick="goWeekView(${n})"><div class="wk-num">W${n}</div><div class="wk-stat">No data</div></div>`;
    const g = weekAgg(wk);
    return `<div class="home-week-card has-data" onclick="goWeekView(${n})">
      <div class="wk-num">W${n}</div>
      <div class="wk-stat">${g.totalBlocks} blocks · ${wk.days.length}/7 days</div>
      <div class="wk-charge ${g.charge<0?'cell-pos':(g.charge>0?'cell-neg':'')}">${fmtInr(g.charge)}</div>
    </div>`;
  }).join('');

  app.innerHTML = `
    <div class="home-hero">
      <div>
        <div class="project-title-row"><h1 style="font-family:var(--display);font-size:23px;font-weight:700;margin:0;">${state.projectMeta.plant || state.projectMeta.name}</h1></div>
        <div class="sub" style="font-size:12.5px;color:var(--muted);margin-top:3px;">${state.projectMeta.plant} · CERC DSM Regulations 2024</div>
      </div>
      <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
        <div class="nav-tabs"><div class="nav-tab active">🏠 Home</div><div class="nav-tab" onclick="goWeekView(${state.currentWeek})">📊 Week View</div></div><div class="thdc-save-controls"><button class="btn btn-primary btn-sm" onclick="THDC_MANUAL_SAVE()">💾 Save Data</button><button class="btn btn-sm" onclick="THDC_EXPORT_BACKUP()">⇩ Backup</button><button class="btn btn-sm" onclick="THDC_IMPORT_BACKUP()">⇧ Restore</button><span class="thdc-save-status" data-save-status>Not saved yet</span></div>
        <button class="btn btn-sm" onclick="openFormulaModal()">⚙ Formula Settings</button>
        <div class="user-chip">📱 <b>${state.auth.mobile||''}</b><button onclick="logout()">Logout</button></div>
      </div>
    </div>
    <div class="kpi-grid" style="grid-template-columns:repeat(5,1fr);margin-bottom:20px;">
      <div class="kpi-card"><div class="kpi-label">Weeks Loaded</div><div class="kpi-value">${totalWeeksLoaded}<span class="unit">/ 52</span></div></div>
      <div class="kpi-card"><div class="kpi-label">Total Blocks</div><div class="kpi-value">${totalBlocks.toLocaleString('en-IN')}</div></div>
      <div class="kpi-card"><div class="kpi-label">Cumulative Scheduled</div><div class="kpi-value" style="font-size:16px;">${fmtMWh0(totalS)}<span class="unit">MWh</span></div></div>
      <div class="kpi-card"><div class="kpi-label">Cumulative Deviation</div><div class="kpi-value" style="font-size:16px;">${totalDev>=0?'+':''}${fmtMWh0(totalDev)}<span class="unit">MWh</span></div></div>
      <div class="kpi-card ${totalCharge<0?'c-green':(totalCharge>0?'c-red':'')}"><div class="kpi-label">Cumulative DSM Charge</div><div class="kpi-value ${totalCharge<0?'green':(totalCharge>0?'red':'')}" style="font-size:16px;">${fmtInr(totalCharge)}</div></div>
    </div>
    <div class="panel">
      <div class="panel-head">
        <div class="panel-title">All Weeks <span class="n">click any week to open its dashboard</span></div>
        <button class="btn btn-primary btn-sm" onclick="goWeekView(${state.currentWeek}); openModal('pasteModal');">⇪ Paste Excel Data</button>
      </div>
      <div class="home-grid">${weekCards}</div>
    </div>
    <footer>${state.projectMeta.name} · Calculation engine matches the source workbook's <code>Calculation</code> sheet exactly. ${state.storageAvailable ? 'Data persists automatically in this session.' : 'Persistent storage unavailable in this context — use Export Week to keep a copy.'}</footer>
  `;
}

