/* ================= RENDER: INJECTION CLASSIFICATION ================= */
function renderInjection(){
  const week = weekObj();
  const g = weekAgg(week);
  let overE=0, underE=0, overCharge=0, underCharge=0;
  week.days.forEach(d=>d.blocks.forEach(b=>{
    const r = revisionAwareBlock(d,b);
    if(r.dev>0){ overE+=r.dev; overCharge+=r.charge; }
    else if(r.dev<0){ underE+=r.dev; underCharge+=r.charge; }
  }));
  const total = g.totalBlocks||1;
  document.getElementById('injGrid').innerHTML = `
    <div class="inj-card over">
      <h4>Over-Injection <span style="color:var(--muted-2);font-weight:400;">(Actual &gt; Schedule)</span></h4>
      <div class="inj-row"><span>Blocks</span><b>${g.over}</b></div>
      <div class="inj-row"><span>% of blocks</span><b>${fmtPct(g.over/total*100)}</b></div>
      <div class="inj-row"><span>Total energy</span><b>+${fmtMWh(overE)} MWh</b></div>
      <div class="inj-row"><span>Financial impact</span><b>${fmtInr(overCharge)}</b></div>
    </div>
    <div class="inj-card under">
      <h4>Under-Injection <span style="color:var(--muted-2);font-weight:400;">(Actual &lt; Schedule)</span></h4>
      <div class="inj-row"><span>Blocks</span><b>${g.under}</b></div>
      <div class="inj-row"><span>% of blocks</span><b>${fmtPct(g.under/total*100)}</b></div>
      <div class="inj-row"><span>Total energy</span><b>${fmtMWh(underE)} MWh</b></div>
      <div class="inj-row"><span>Financial impact</span><b>${fmtInr(underCharge)}</b></div>
    </div>
  `;

  destroyChart('injDonut');
  const canvas = document.getElementById('chartInjDonut');
  if(canvas && typeof Chart !== 'undefined' && week.days.length){
    state.charts.injDonut = new Chart(canvas, {
      type:'doughnut',
      data:{
        labels:['Over-Injection','Under-Injection','No Deviation'],
        datasets:[{ data:[g.over, g.under, g.none], backgroundColor:['#215CD1','#C1403A','#C7CDD6'], borderWidth:2, borderColor:'#FFFFFF' }]
      },
      options:{
        responsive:true, maintainAspectRatio:false, cutout:'62%',
        plugins:{
          legend:{position:'bottom', labels:{boxWidth:9, font:{size:10.5}, padding:8}},
          tooltip:{callbacks:{ label: (ctx)=> ctx.label+': '+ctx.parsed+' blocks ('+((ctx.parsed/total)*100).toFixed(1)+'%)' }}
        }
      }
    });
  }
}

